query Search($countryId: String!, $search: String!) {
  searchEntities(countryId: $countryId, search: $search) {
    edges {
      node {
        cinemas {
          id
          lat
          lng
          name
          type
          cityId
          vistaId
          timeZone
          cityName
          cityRegion
          businessType
          experiences {
            name
          }
          countryId
        }
        movies {
          id
          name
          countryId
          media {
            platform
            resources {
              type
              code
              resource
              sizes {
                large
                small
                medium
              }
            }
          }
        }
      }
    }
  }
}
